impl<S: gx::Slots, T: gx::Coef, O: gx::Orientation, OV: gx::Orientation> gx::Transform<Multivector<S, T, O>> for gx::Unit<Vector<(), T, OV>> {
    type Output = Multivector<S, T, O>;
    #[inline(always)]
    fn transform(self, x: Multivector<S, T, O>) -> Multivector<S, T, O> {
        let v = self.into_inner().c;
        #[cfg(feature = "check-units")]
        {
        let u1 = v[1] * v[1];
        let u2 = v[0].mul_add(v[0], u1);
        let u3 = u2 - T::from_i64(1);
            T::check_unit(&[u3]);
        }
        if let Some(xv) = gx::slots::values::<S, T, 4>(&x.c) {
        let t0 = v[0] * v[0];
        let t1 = v[1] * v[1];
        let t2 = v[0] * v[1];
        let t3 = t0 - t1;
        let t5 = xv[2] * t2;
        let t6 = xv[1] * t2;
        let t8 = t5 * T::from_i64(2);
        let t9 = xv[1].mul_add(t3, t8);
        let t10 = t6 * T::from_i64(2);
        let t11 = (-xv[2]).mul_add(t3, t10);
        let t12 = -xv[3];
        let t13 = t0 + t1;
        let t14 = xv[0] * t13;
        let t15 = t12 * t13;
            return Multivector { o: core::marker::PhantomData, c: gx::orientation::reflect::<O, S, T, 4>(gx::slots::from_values::<S, T, 4>([t14, t9, t11, t15]), [false, true, true, false]) };
        }
        let m0 = v[0] * v[0];
        let m1 = v[1] * v[1];
        let m2 = v[0] * v[1];
        let m3 = m0 - m1;
        let m4 = m0 + m1;
        let m5 = m2 * T::from_i64(2);
        let m6 = -m3;
        let m7 = -m4;
        let x = x.c.map(gx::SlotArr::<S, T>);
        Multivector { o: core::marker::PhantomData, c: gx::orientation::reflect::<O, S, T, 4>([(x[0].scale(m4)).0, (x[1].scale(m3) + x[2].scale(m5)).0, (x[1].scale(m5) + x[2].scale(m6)).0, (x[3].scale(m7)).0], [false, true, true, false]) }
    }
}

